<script setup lang="ts">
/**
 * Steps pointing at the parts of a page (`design/components/tour.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tour.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useId, useTemplateRef, watch } from 'vue'

import * as zag from '@zag-js/dialog'
import { normalizeProps, useMachine } from '@zag-js/vue'

import {
  agentMember,
  revealTourTarget,
  tourPlacement,
  tourTarget,
  tourTargetRect,
  tourViewport,
  useDirection,
} from '@polymorph/vue'
import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/overlays/tour.module.css'
import Button from '../controls/Button.vue'

export interface TourStep {
  /** The step's key, unique in the tour. */
  id: string
  /** The `name` of the `Tour.Target` the step points at. Without one, the step is drawn centred. */
  target?: string
  title: string
  /** A sentence or two about the target, as text. */
  body: string
  /** The side of the target the panel opens on, when it fits there. */
  side?: 'top' | 'right' | 'bottom' | 'left'
}

export interface TourMessages {
  next: string
  previous: string
  /** The last step's forward control, which ends the tour. */
  done: string
  /** The close control's accessible name. */
  close: string
  /** The position line, counting from 1: "Step 2 of 5". */
  position: (position: number, count: number) => string
}

export type TourEnd = 'finished' | 'dismissed'

export interface TourProps {
  defaultOpen?: boolean
  defaultStep?: number
  messages?: TourMessages
  open?: boolean
  /**
   * The current step's index, clamped to the steps.
   */
  step?: number
  steps: readonly TourStep[]
}

defineOptions({ name: 'Tour', inheritAttrs: false })

const props = withDefaults(defineProps<TourProps>(), {
  defaultOpen: undefined,
  messages: () => ({
    next: 'Next',
    previous: 'Previous',
    done: 'Done',
    close: 'Close',
    position: (position: number, count: number) => `Step ${position} of ${count}`,
  }),
  open: undefined,
})
const emit = defineEmits<{ end: [reason: TourEnd]; stepChange: [index: number] }>()
const uid = useId()
const uncontrolledStep = ref(props.defaultStep ?? 0)
const ending = ref(null as 'finished' | 'dismissed' | null)
const geometry = ref(
  null as {
    x: number
    y: number
    placement: 'top' | 'right' | 'bottom' | 'left' | 'center'
    hole: { x: number; y: number; width: number; height: number } | null
  } | null,
)
const panel = useTemplateRef<HTMLElement>('panel')
const positioner = useTemplateRef<HTMLElement>('positioner')
const scrim = useTemplateRef<HTMLElement>('scrim')
const count = computed(() => props.steps.length)
const index = computed(() =>
  Math.min(Math.max(props.step ?? uncontrolledStep.value, 0), Math.max(count.value - 1, 0)),
)
const current = computed(() => props.steps[index.value])
const first = computed(() => index.value === 0)
const last = computed(() => index.value === count.value - 1)
const drawnAt = computed(() => geometry.value?.placement ?? 'center')
const cutOut = computed(() => geometry.value?.hole ?? null)
const go = computed(() => (next: number): void => {
  uncontrolledStep.value = next
  emit('stepChange', next)
})
const closed = computed(() => (open: boolean): void => {
  if (open) return
  const reason = ending.value ?? 'dismissed'
  ending.value = null
  emit('end', reason)
})
const place = computed(() => (): void => {
  if (positioner.value == null || current.value === undefined) return
  const rect = tourTargetRect(tourTarget(current.value.target))
  const next = {
    ...tourPlacement(
      rect,
      { width: positioner.value.offsetWidth, height: positioner.value.offsetHeight },
      tourViewport(),
      current.value.side,
    ),
    hole: rect,
  }
  if (JSON.stringify(next) !== JSON.stringify(geometry.value)) geometry.value = next
})
const follow = computed(() => (): (() => void) => {
  const again = (): void => place.value()
  window.addEventListener('resize', again)
  document.addEventListener('scroll', again, { capture: true, passive: true })
  return () => {
    window.removeEventListener('resize', again)
    document.removeEventListener('scroll', again, { capture: true })
  }
})
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    open: props.open === undefined ? undefined : props.open && count.value > 0,
    defaultOpen: props.defaultOpen === true && count.value > 0,
    preventScroll: false,
    closeOnInteractOutside: false,
    initialFocusEl: () => panel.value,
    onOpenChange: (details) => {
      closed.value(details.open)
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const end = computed(() => (reason: 'finished' | 'dismissed'): void => {
  ending.value = reason
  api.value.setOpen(false)
})
const show = computed(() => (): void => {
  if (!api.value.open || current.value === undefined) return
  revealTourTarget(tourTarget(current.value.target))
  place.value()
  requestAnimationFrame(() => place.value())
})
const scrimPresent = usePresence(
  () => api.value.open && current.value !== undefined,
  scrim,
  'dialog.scrim',
)
const panelPresent = usePresence(
  () => api.value.open && current.value !== undefined,
  panel,
  'popover.panel',
  {
    get side() {
      return drawnAt.value === 'center' ? undefined : drawnAt.value
    },
    align: 'center',
  },
)
const effect1 = () => {
  show.value()
}
onMounted(effect1)
watch(() => [api.value.open, index.value], effect1, { flush: 'post' })
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const run = () => {
    place.value()
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [positioner.value]) if (element) resize?.observe(element)
  release2 = () => {
    resize?.disconnect()
  }
  run()
}
onMounted(effect2)
watch(() => api.value.open, effect2, { flush: 'post' })
onBeforeUnmount(() => release2?.())
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = follow.value()
  release3 = () => {
    ran()
  }
}
onMounted(effect3)
watch(() => api.value.open, effect3, { flush: 'post' })
onBeforeUnmount(() => release3?.())
const effect4 = () => {
  api.value.open && panel.value?.focus()
}
watch(() => index.value, effect4, { flush: 'post' })
let release5: (() => void) | undefined
const effect5 = () => {
  release5?.()
  const ran = agentMember({
    member: 'Tour',
    element: () => panel.value,
    state: () => ({
      open: api.value.open,
      step: index.value,
      steps: props.steps.map((each) => ({ id: each.id, title: each.title, body: each.body })),
    }),
    actions: {
      next: () =>
        (() => {
          if (!api.value.open) throw new Error('The tour is not open.')
          if (last.value) throw new Error('On the last step, an agent ends a tour with dismiss.')
          go.value(index.value + 1)
        })(),
      previous: () =>
        (() => {
          if (!api.value.open) throw new Error('The tour is not open.')
          if (first.value) throw new Error('This is the first step.')
          go.value(index.value - 1)
        })(),
      dismiss: () => api.value.open && end.value('dismissed'),
    },
    withholds: () => panel.value,
  })
  release5 = () => {
    ran()
  }
}
onMounted(effect5)
onBeforeUnmount(() => release5?.())
</script>

<template>
  <Teleport to="body">
    <!-- scrim -->
    <div
      v-if="scrimPresent"
      ref="scrim"
      v-bind="api.getBackdropProps()"
      :class="[
        cutOut !== null ? styles.spotlight : undefined,
        cutOut === null ? styles.scrim : undefined,
      ]"
      :style="{
        '--pm-tour-hole-x': cutOut === null ? undefined : `${cutOut.x}px`,
        '--pm-tour-hole-y': cutOut === null ? undefined : `${cutOut.y}px`,
        '--pm-tour-hole-width': cutOut === null ? undefined : `${cutOut.width}px`,
        '--pm-tour-hole-height': cutOut === null ? undefined : `${cutOut.height}px`,
      }"
      :hidden="undefined"
      aria-hidden="true"
      data-tour-part="scrim"
    />
    <div
      v-if="panelPresent"
      ref="positioner"
      v-bind="api.getPositionerProps()"
      :class="styles.positioner"
      :style="{ '--pm-tour-x': `${geometry?.x ?? 0}px`, '--pm-tour-y': `${geometry?.y ?? 0}px` }"
      :data-placement="drawnAt"
    >
      <!-- panel -->
      <div
        ref="panel"
        v-bind="api.getContentProps()"
        :class="styles.panel"
        :hidden="undefined"
        :data-step="current?.id"
        data-member="tour"
      >
        <!-- title -->
        <h2 v-bind="api.getTitleProps()" :class="styles.title">
          {{ current?.title }}
        </h2>
        <!-- description -->
        <div v-bind="api.getDescriptionProps()" :class="styles.description">
          <!-- body -->
          <p :class="styles.body">
            {{ current?.body }}
          </p>
          <!-- position -->
          <p :class="styles.position" data-tour-part="position">
            {{ messages.position(index + 1, count) }}
          </p>
        </div>
        <!-- actions -->
        <div :class="styles.actions" data-tour-part="actions">
          <Button
            v-if="!first"
            variant="outline"
            tone="neutral"
            size="sm"
            :label="messages.previous"
            @click="go(index - 1)"
          />
          <Button
            size="sm"
            :label="last ? messages.done : messages.next"
            @click="last ? end('finished') : go(index + 1)"
          />
        </div>
        <!-- close -->
        <div :class="styles.close" data-tour-part="close">
          <Button
            variant="ghost"
            tone="neutral"
            size="sm"
            :iconOnly="true"
            icon="close"
            :label="messages.close"
            @click="end('dismissed')"
          />
        </div>
      </div>
    </div>
  </Teleport>
</template>
